export function generateVocabularyHtml(item) {
  const familyJson = JSON.stringify(
    (item.family || []).map((w, index) => ({
      word: w,
      hw: true,
      freq: 100 - index * 10,
    }))
  ).replace(/"/g, '&quot;');

  return `
    <article>
      <h1 class="dynamictext">${item.word}</h1>
      <div class="ipa-with-audio">
        <div class="us-flag-icon"></div>
        <div data-audio="${item.audio?.us ? item.audio.us.replace(/\.mp3$/, '').toUpperCase() : ''}"></div>
        <span class="span-replace-h3">/${item.ipa?.us || '---'}/</span>
      </div>
      <div class="ipa-with-audio">
        <div class="uk-flag-icon"></div>
        <audio src="https://audio.vocabulary.com/1.0/uk/${item.audio?.uk ? item.audio.uk.replace(/\.mp3$/, '') : ''}.mp3"></audio>
        <span class="span-replace-h3">/${item.ipa?.uk || '---'}/</span>
      </div>
      <div class="word-area">
        <p class="short">${item.def}</p>
        <p class="long">Comprehensive long definition explaining the concept of ${item.word}.</p>
      </div>
      <div class="word-definitions">
        <ol>
          <li><div class="definition">${item.def}</div></li>
        </ol>
      </div>
      <vcom:wordfamily lang="en" word="${item.word}" data="${familyJson}">
    </article>
  `;
}

export function generateCambridgeHtml(item) {
  return `
    <div class="pr entry-body__el">
      <div class="pos-header dpos-h">
        <span class="hw dhw">${item.word}</span>
        <span class="pos dpos">${item.pos}</span>
        <span class="uk dpron-i">
          <span class="ipa dipa lpr-2 lpl-1">${item.ipa?.uk || '---'}</span>
          <audio id="audio_uk">
            <source type="audio/mpeg" src="/media/english/uk_pron/${item.audio?.uk || ''}" />
          </audio>
        </span>
        <span class="us dpron-i">
          <span class="ipa dipa lpr-2 lpl-1">${item.ipa?.us || '---'}</span>
          <audio id="audio_us">
            <source type="audio/mpeg" src="/media/english/us_pron/${item.audio?.us || ''}" />
          </audio>
        </span>
      </div>
      <div class="def-block ddef_block">
        <span class="guideword dsense_gw"><span>CORE SENSE</span></span>
        <div class="def ddef_d db">${item.def}:</div>
        <div class="examp dexamp"><span class="eg deg">${item.example}</span></div>
      </div>
      <span class="inf-group">
        <span class="inf-letter">forms</span>
        ${(item.family || []).map((w) => `<b class="inf-word">${w}</b>`).join(' ')}
      </span>
    </div>
  `;
}
